from report_model import section, row as R

section(21, "歴史と背景", "いまの構成は、1つの製品が一度に生まれたものではありません。『遠い・認証が大変・内部へ安全に接続したい・FWを増やしたい』という別々の課題への対応が積み重なっています。背景欄は機能の位置付けを説明する整理です。", [
R("2008-11-18 CloudFront", "遠くの人にも、近くに案内窓口を置きたい。", "CloudFrontがpublic betaとして登場しました。配信拠点を自前で世界中に置く負担を減らす方向のサービスです。", "今回もグローバルな入口を担いますが、token発行処理はCognitoの役割です。", "S43"),
R("2009-08 VPC", "会社専用の敷地をクラウドにも作りたい。", "VPCにより、隔離したアドレス空間や既存ネットワークとの接続を構成する道が整いました。What's Newは8月26日付です。", "AWSアカウントとVPCの境界が異なることを理解する出発点です。", "S44"),
R("2012-10 OAuth 2.0", "合言葉をあちこちへ配らず、用途を限定した通行証を渡したい。", "RFC 6749がOAuth 2.0の枠組みを標準化しました。client credentialsは機械自身が権限を得るためのgrantです。", "機械に人間のログイン画面を操作させる必要を減らします。", "S41"),
R("2015-04-09 ECS GA", "たくさんの担当者を起動・配置・回復させたい。", "ECSがGAとなり、複数ホストへコンテナを配置する管理をサービス化しました。アプリを包むだけでなく、維持・増減する仕組みが必要でした。", "今回の最終処理先はECSが管理するtaskです。", "S45"),
R("2015-05 JWT標準", "事務室へ毎回電話せず、本物の通行証を確認したい。", "RFC 7519がJWTの形式を定義しました。claimを署名等で保護して伝えるための枠組みです。", "JWTという形式だけで安全が完成せず、信頼する発行者、署名、期限、権限を検証します。", "S42"),
R("2015-07-09 API Gateway", "アプリごとに受付を作るのは大変。", "API GatewayがAPI公開・認可・トラフィック管理等を共通のサービスとして提供し始めました。", "アプリは業務処理に集中し、入口の共通処理を分担できます。", "S46"),
R("2015-10-06 WAF", "ポートを開くだけでは、危険な注文用紙を防げない。", "AWS WAFが登場しました。HTTPの内容を使ったルールでWeb向け攻撃に対応する層です。", "ネットワークの到達許可、本人確認、HTTP内容検査を分ける理由につながります。", "S47"),
R("2016-07-28 User Pools GA", "ユーザーの登録と認証を毎回作り直したくない。", "Cognito User PoolsがGAとなりました。人のユーザー管理が出発点ですが、現在のM2Mはアプリを主体として利用します。", "User Pools登場日とclient_credentials対応日を同じものとして扱いません。", "S48"),
R("2016-08-11 ALB", "注文の種類を見て、担当机を変えたい。", "ALBがL7の負荷分散として登場しました。URLやHTTPを扱うアプリ、コンテナの普及と相性のよい分担です。", "今回のGWLBは検査員の分散、ALBは業務担当の分散という別の役割です。", "S49"),
R("2017-08-10 Cognito M2M", "人が操作しないシステムにも通行証を出したい。", "CognitoのOAuth 2.0機能拡張にclient credentials、custom scopes、resource serversが含まれました。", "本資料のtoken取得とscope認可の直接の背景です。", "S50"),
R("2017-11 PrivateLink", "敷地全部をつながず、必要なサービスだけ使いたい。", "AWS PrivateLinkが発表され、公開インターネットを介さずサービス単位で接続する方式が広がりました。", "GWLB endpoint serviceとGWLBEの別アカウント接続も、この系統の技術です。", "S51 S34"),
R("2017-11-30 REST VPC Link", "外の受付から、非公開の業務システムへつなぎたい。", "API Gatewayのprivate VPC integrationが登場しました。当時の構成ではNLBを利用するVPC Linkが基本でした。", "古い記事にRESTはNLB必須と書かれる理由です。", "S52"),
R("2020 HTTP APIのALB連携", "別種の軽量APIでも、内部サービスへつなぎたい。", "HTTP APIではALB等へのprivate integrationが提供されてきました。RESTとHTTP APIの機能差が、似た説明の混同を生みやすい点です。", "VPC Link V2の名前だけでAPI種別を判断しません。", "S55 S28"),
R("2020-11-10 GWLB", "FWを1台の固定の道にせず、増やして運用したい。", "GWLBが登場し、透過的な通過点とアプライアンスへの負荷分散を組み合わせました。GWLBEで検査サービスを差し込む方式です。", "中央で検査を管理しながら各業務VPCへ出入口を置く背景です。", "S53 S56"),
R("2021-08-30 VPC経路拡張", "学校の外門だけでなく、区画同士の通路も検査したい。", "localより具体的なルートによるsubnet間の検査挿入が可能になりました。以前の制約を記した資料との読み分けが必要です。", "今回のVPC Link subnet↔ALB subnetでGWLBEを使う設計の重要な前提です。", "S54 S15"),
R("2025-06 ACM exportable", "検査所にもサーバーの証明書を安全に用意したい。", "ACM public certificateをexportableとして発行する選択肢が現在提供されています。2025-06-17以前の証明書はexportできません。", "『ACMの公開証明書の秘密鍵は全部export不可』という古い説明を一般化しません。", "S23 S67"),
R("2025-11-12 ALB JWT発表", "案内係自身にも機械用の通行証を確認させたい。", "ALBのJWT検証機能が発表され、M2M/S2S tokenを検証する選択肢が加わりました。", "ALBの認証を対話型Cognitoログインだけと説明しないよう更新が必要です。", "S30 S29"),
R("2025-11-21 REST→ALB", "間のNLBを減らして、ALBへ直接つなぎたい。", "REST APIでVPC Link V2によるALB直接private integrationが利用可能になりました。", "ユーザー指定のREST＋V2＋ALBを成立させる、今回もっとも重要な更新です。", "S01 S02"),
R("2026-01-30 secret rotation", "合言葉を止めずに入れ替えたい。", "Cognitoの履歴に、app clientあたり最大2個のsecretを使うrotation機能が記載されています。", "旧clientを必ず作り直す前提ではなく、現在の追加・切替・削除方式を検討できます。", "S57 S08"),
R("確認時点：2026-10-03", "新しい窓口や機能を、選択肢として理解します。", "現行公式文書にはGetClientTokenによるdomainless M2Mや、RESTのresponse streamingもあります。主構成は指定どおりCloudFront経由token取得＋通常のREST応答です。", "機能の存在を確認した日と、その機能の公開日を混同しません。公開日未確認の機能へ日付を推測して付けていません。", "S31 S60"),
])

section(22, "よくある誤解", "似た名前と古い仕様から生じる誤解をまとめます。右側の条件を確認して、構成図と実設定を一致させてください。", [
R("CloudFrontがJWTを発行？", "発行するのは事務室です。", "CloudFrontは入口/配送、Cognitoは発行と署名を担います。エッジが近いことと、発行者の所在は別です。", "tokenのissuerをCloudFrontのドメインと思い込まないようにします。", "S05 S06 S10"),
R("CognitoがECSへtokenを送る？", "一度ロボットの手元へ戻ります。", "tokenを取得する呼出しと、それを添えて業務APIを呼ぶ処理は呼出側が行う別動作です。", "戻り経路も認証用と業務用を分けます。", "S06 S07"),
R("API→WAF→別REST装置？", "同じ受付の中に、複数の確認があるイメージです。", "Regional REST APIはAPI GatewayのAPI種別/公開方式です。WAFはstageへの関連付けでHTTP要求を検査します。", "全体図の箱は機能を示しており、必ずしも別IPのネットワークhopを示しません。", "S12 S13"),
R("IGWで全AWS入口を検査？", "自分の学校の門では、町の別窓口の来客を捕まえられません。", "公開API Gatewayへの着信を、自分のVPCのIGW edge routeへ強制することはできません。", "もし『公開APIの手前で必ず自社FWを通す』要件なら、入口設計から別途見直します。", "S13 S14 S59"),
R("GWLBEへ0/0だけ追加？", "広い案内より、近所の詳しい案内が優先されます。", "Link→ALBが同じVPC内ならlocal /16が0/0より優先します。ALB subnet /24へのルートが必要です。", "デフォルトルートだけ変えて検査できたと判断しません。", "S15"),
R("FWを通せば本文が読める？", "鍵のない検査員は箱を開けられません。", "TLSのままでは本文やBearer tokenは暗号化されています。GENEVEは包む機能で、復号機能ではありません。", "復号の要否をセキュリティ要件に明記します。", "S17 S21 S22"),
R("GWLBが侵入を検知？", "配分係と検査員は別です。", "GWLBは対象アプライアンスへ振り分けます。脅威判定はVM-Seriesの機能・設定に依存します。", "GWLB healthyだけで脅威防御の有効化を確認したことにはなりません。", "S17 S20 S21"),
R("ALB→ECSも同じ接続？", "案内係で会話が一度切り替わります。", "ALB frontendとbackendは別接続です。ECSの返事はALBへ戻り、そこからVPC Linkへ返ります。", "taskの外向きNATを、通常のAPI応答経路として描きません。", "S25 S64"),
R("同じAZ名なら同じ場所？", "組織ごとに呼び方が違うことがあります。", "別アカウントでAZ名と物理AZの対応が異なる場合があります。", "providerとconsumerの対応はAZ IDで確認します。", "S16"),
R("RESTではNLBが必須？", "その説明は古い通路の話かもしれません。", "現行RESTはVPC Link V2でALBへ直接統合できます。V1の制約とは区別します。", "AWS公式の更新日と対象API種別を確認します。", "S01 S02 S52"),
R("本当にIGWが必要なら？", "公道から学校の門へ来る別の入口を使う場合です。", "例としてinternet-facing ALBへの着信ならIGW edge route→GWLBE→検査→ALBという方式があります。ただし今回の公開API Gateway＋VPC Linkの前段と同じものではありません。", "API入口をPrivate API＋Interface endpointへ変える案も、接続方法が変わる別設計です。要求に応じて比較します。", "S58 S59"),
R("ALBはM2M tokenを確認できない？", "いまは追加の確認機能があります。", "現行ALBのJWT検証を利用できます。API Gatewayでの確認は主構成、ALBでの確認は任意の追加層です。", "古いauthenticate-cognitoだけの説明と区別します。", "S29 S30"),
R("NLB/TGWを追加すれば必ず安全？", "通路を増やすだけでは、道しるべの誤りは直りません。", "必要な機能に応じて追加するもので、往復対称性、FW状態、TLS検査、認可が正しく設定されていることが重要です。", "要件に不要な中継を増やさず、経路と検査結果を証跡で確認します。", "設計上の判断・S15 S19"),
])

section(23, "構築と検証手順", "この章は実環境で行う受入確認の案です。AWSリソースは作成・変更しておらず、以下のAWS疎通試験はすべて未実施です。文書生成の検証とは分けて扱います。", [
R("01 要件を固定", "どの通路で、何を検査するかを決めます。", "IPv4/IPv6、Region、Accounts、API種別、scope、対象データ、TLS本文検査、許容停止、ログ、負荷を明文化します。", "完了の証拠：設計前提・責任分界・許容値が承認済み。実環境確認：未実施。", "設計手順"),
R("02 既存設定を確認", "いまの地図を見てから新しい道を引きます。", "subnet/RT/SG/NACL、VPC Link version、ALB listener、FW構成、AZ ID、CIDR重複、既存NAT/TGWを読み取ります。", "完了の証拠：AS-IS一覧と変更差分。既存通信の影響を確認。実環境確認：未実施。", "S02 S03 S15 S16"),
R("03 検査サービスを準備", "検査所を先に動ける状態にします。", "VM-Series設定、GWLB target group、health check、endpoint serviceの権限と接続承認を整えます。", "完了の証拠：対象AZでFW healthy、GWLBE available、GENEVE双方向。実環境確認：未実施。", "S16 S20 S21 S32"),
R("04 ALB/ECSを準備", "図書室の担当者が働けることを確認します。", "internal ALB、HTTPS listener、task/target group、health endpoint、SG、証明書をそろえます。", "完了の証拠：target healthy、意図したHost/pathで業務応答。実環境確認：未実施。", "S24 S25 S64"),
R("05 Linkと往復経路", "行き帰り両方の道しるべを設置します。", "分離したsubnetでV2を作り、14章のルートと17章の許可を実値に合わせます。GWLBE subnetは検査後の配送を担当します。", "完了の証拠：4組合せの往復対称性とFW session。実環境確認：未実施。", "S03 S15 S19"),
R("06 認証とAPIを設定", "通行証と入口の規則を対応させます。", "M2M client/scope、Cognito authorizer、メソッドscope、regional WAF、HTTP_PROXY integration-target/URIを設定しstageへdeployします。", "完了の証拠：実URLで正しいtokenが成功。実環境確認：未実施。", "S04 S06 S11 S12 S61"),
R("07 認可の異常試験", "偽物や期限切れの通行証が通れないか調べます。", "tokenなし、改ざんtoken、期限切れ、別pool、scope不足、許可外clientの扱いを確認します。", "期待：仕様に従い拒否。正常tokenだけでは検証不足。実環境確認：未実施。", "S10 S11"),
R("08 FW通過の証明", "注文が必ず検査所へ来た証拠を取ります。", "承認済みの試験通信をFWルールで識別し、allow/dropの両方、5-tuple、往復bytes、API/ALB応答を照合します。", "期待：permitは成功、検査用denyは後段へ到達しない。実環境確認：未実施。", "S19 S21 S35"),
R("09 TLS復号の証明", "箱の中身まで実際に検査できたか調べます。", "FWのdecryption記録、対象TLS版/cipher、証明書更新、復号失敗時の処理、許可された脅威検証ケースを確認します。", "期待：機密性を維持し、必要な本文検査が実施される。実環境確認：未実施。", "S21 S22 S23"),
R("10 迂回とクロスAZ", "裏道や別校舎でも規則が崩れないか調べます。", "A→A/A→B/B→A/B→B、想定外送信元、IPv6、API cache、ALB直接アクセス、不要メソッドを確認します。", "期待：検査対象が意図せずlocal直通しない。実環境確認：未実施。", "S15 S16 S19"),
R("11 障害と再接続", "検査員や校舎が使えなくなったときの動きを確かめます。", "テスト環境でFW異常、target deregistration、endpoint/AZ障害相当、証明書不一致を計画的に試します。", "既存session、新規session、復旧時間、再試行、二重処理を記録。実環境確認：未実施。", "S19 S20 S37"),
R("12 負荷・大きなデータ", "忙しい時間や大きな荷物でも調べられるか確認します。", "実際の接続再利用、token更新、TLS復号、本文サイズ、MTU、ログ量を含む負荷で遅延・FW容量を測ります。", "期待：合意した性能と検査品質を満たす。実環境確認：未実施。", "S18 S21 S27"),
R("13 変更と復旧の手順", "道を変えるときに、戻す順序も用意します。", "ルート・SG・認可を段階的に変更し、監視とロールバック条件を定義します。未承認の本番操作は行いません。", "復旧時にFW迂回を許すか等は業務要件で決定。資料作成では外部変更なし。", "設計手順"),
R("14 完了の判断", "本が届くだけでなく、必要な確認を全部通った証拠を残します。", "正しい認可、往復検査、復号範囲、迂回防止、障害回復、ログ秘匿を証拠付きで確認して受入とします。", "この成果物の静的なルート照合は、AWSでのpacket経路の実測を置き換えません。", "設計手順"),
])

GLOSSARY = [
("M2M", "機械と機械のやり取り。", "Machine-to-Machine。人が画面で操作せずサーバー等が通信します。", "S07"),
("OAuth 2.0", "使ってよい権限を渡す共通の決まり。", "認可の枠組み。client credentialsはそのgrantの1つです。", "S41"),
("JWT", "情報と本物の印が付いた通行証。", "JSON Web Token。デコードと署名検証は異なります。", "S42"),
("Bearer", "持っている人が利用できる方式。", "漏えい時は他人に使われ得るためTLSと安全な保管が必要です。", "S06"),
("scope", "許された作業の名前。", "books-api/books.readのような操作の許可単位です。", "S07"),
("claim", "通行証に書かれた1項目。", "iss、exp、client_id、scope等の情報です。", "S09"),
("JWKS", "本物の印を確かめる公開見本帳。", "署名検証用の公開鍵集合。秘密鍵ではありません。", "S10"),
("認証", "だれかを確かめること。", "M2Mではclient ID/secret等で機械の主体を確認します。", "S08"),
("認可", "その操作をしてよいか決めること。", "正しい機械でも、持たないscopeや他者データは拒否し得ます。", "S07"),
("TLS / HTTPS", "鍵を掛けて会話する仕組み。", "HTTPSはTLSで保護されたHTTPです。中継ごとに接続が分かれ得ます。", "S04 S64"),
("SNI / Host", "接続先の名前を伝える仕組み。", "SNIはTLS時、HostはHTTPで使う名前。証明書やALB ruleとの整合が必要です。", "S04"),
("ACM", "証明書の管理サービス。", "AWS Certificate Manager。Cognitoカスタムdomain用のRegion等に条件があります。", "S05 S23"),
("Region / AZ", "地域と、その中の障害を分けた拠点。", "同じRegion内の複数AZを用いて可用性を高めます。", "S03 S16"),
("VPC / subnet", "専用の敷地と、その区画。", "ネットワーク空間とIP範囲。subnet単位でルートを関連付けます。", "S15"),
("CIDR / prefix", "住所のまとまりの書き方。", "10.20.30.0/24は範囲の例。/24は/16より細かい指定です。", "S15"),
("ENI", "クラウドの仮想ネットワークカード。", "VPC Link、task等のVPC内接続に関係します。", "S03 S24"),
("IGW / NAT", "外へ出る門と、住所を変換する仕組み。", "IGWはVPCのインターネット接続部品。NATはアドレス変換で、API認可とは別です。", "S14 S15"),
("VPC Link", "API Gatewayから内部への通路。", "private integrationでバックエンドへ接続します。", "S02 S03"),
("PrivateLink", "必要なサービスに限定した専用接続。", "VPC境界を越えてサービスを非公開接続する技術です。", "S34"),
("GWLBE", "GWLBの検査サービスへの出入口。", "Gateway Load Balancer endpoint。route tableのtargetとして使います。", "S16"),
("GWLB", "検査アプライアンスへ通信を振り分ける係。", "Gateway Load Balancer。IPパケットを透過的に扱います。", "S17"),
("GENEVE", "元の荷物を追加の袋に包む方式。", "GWLBとFW間のカプセル化。UDP6081を使います。", "S63"),
("5-tuple / flow", "ひと続きの通信を見分ける5つの情報。", "送受信IP、送受信port、protocol。HTTP要求数とは一致しません。", "S19"),
("stateful / 対称経路", "過去のやり取りを覚え、往復を同じ係が見ること。", "FWのsession維持に重要。行き帰りのrouteをそろえます。", "S19 S21"),
("SG / NACL", "通信を許すルール。", "SGはstateful、NACLはstateless。routeの代わりにはなりません。", "S15 S16"),
("ALB / listener", "HTTPの案内係と、要求を受ける窓口。", "listenerのport/TLSとruleでtarget groupへ振り分けます。", "S25 S64"),
("target group", "仕事を渡す担当者の名簿。", "ALBではtask等、GWLBではFW等を登録します。", "S24 S63"),
("ECS service / task", "人数を保つ管理係と、実際に動く作業単位。", "serviceがtask数等を維持し、task内のコンテナがアプリを実行します。", "S24 S45"),
("health check", "相手が仕事を受けられるか定期確認。", "FWのhealthとALB targetのhealthは別。全経路テストでもありません。", "S20 S24"),
("App-ID / 復号", "何の通信か調べる機能と、暗号を開ける処理。", "可視範囲や対応protocol、設定、ライセンス等に依存します。", "S21 S22"),
("MTU / encapsulation", "1個の荷物の最大寸法と、袋を追加すること。", "追加header分を含めて通れるサイズを確認します。HTTP本文全体の長さとは異なります。", "S18"),
("TGW / appliance mode", "VPCをまとめる交差点と、検査向け経路制御。", "Transit Gatewayを使う集中型設計で対称性を保つための考慮です。主構成にTGWは含めません。", "S19 S21 S56"),
("冪等性", "同じ注文を再送しても二重に処理しない性質。", "応答喪失と業務成功が両立する場合に重要。業務キー等で実装します。", "設計用語"),
]
section(24, "用語集", "略語に出会ったら、この一覧に戻ってください。『やさしい説明』は理解の足場であり、厳密な設定値や対応条件は各章と公式文書で確認します。", [
R(term, easy, detail, "本文の対応章と出典を参照してください。", refs) for term, easy, detail, refs in GLOSSARY
])

section(26, "HTTP例と設定対応", "以下は実行しない説明用の例です。<...>は置き換えが必要なプレースホルダーで、実tokenやsecretは含めていません。スコープとパスの対応を具体化します。", [
R("token取得の要求", "合言葉で『読む通行証』を頼みます。", "POST https://auth.example.com/oauth2/token\nAuthorization: Basic <client_id:client_secretを適切に符号化>\nContent-Type: application/x-www-form-urlencoded\n\ngrant_type=client_credentials&scope=books-api%2Fbooks.read", "OAuthライブラリを使用し、secretの符号化を正しく処理します。Base64文字列をログ出力しません。", "S06 S41"),
R("token取得の応答", "通行証と残り時間が返ります。", '{"access_token":"<JWT>","token_type":"Bearer","expires_in":900}', "900秒は説明用の設定例です。ID token/refresh tokenは含めません。", "S06 S09"),
R("JWTの概念例", "ロボット名と権限と期限が記録されます。", '{"iss":"https://cognito-idp.ap-northeast-1.amazonaws.com/<pool-id>","client_id":"<app-client-id>","sub":"<app-client-id>","token_use":"access","scope":"books-api/books.read","iat":<発行時刻>,"exp":<期限>}', "構造説明のための疑似JSONです。実JWTには他のclaimもあり、headerとsignatureも必要です。", "S09 S10"),
R("業務APIの要求", "今度は通行証で本の情報を頼みます。", "GET https://api.example.com/books/42\nAuthorization: Bearer <JWT>\nAccept: application/json", "client secretは送りません。独自domainをstageへmappingした例です。", "S06 S11 S61"),
R("業務APIの応答", "本の情報が受付経由で返ります。", 'HTTP/1.1 200 OK\nContent-Type: application/json\n\n{"bookId":"42","title":"宇宙のずかん"}', "架空データです。応答自体がCognitoを再度通ったり、tokenを更新したりするわけではありません。", "設計例"),
R("RESTメソッドの対応", "読む注文には、読む許可だけを対応させます。", "GET /books/{bookId}\nAuthorization type: COGNITO_USER_POOLS\nToken source: Authorization\nAuthorization scope: books-api/books.read", "authorizer関連付けとscope設定を行い、stageへdeployします。write操作なら別scopeを設計します。", "S11 S61"),
R("統合の対応", "許可後の送り先を決めます。", "Type: HTTP_PROXY\nConnection type: VPC_LINK\nConnection ID: <VPC Link V2 ID>\nIntegration target: <ALBのloadbalancer/app/... ARN>\nURI: https://backend.example.com:443/<設計したパス>", "RESTではALB ARNを使います。stage付加、path変換、証明書名、ALB Host ruleをそろえます。", "S02 S04"),
R("ルート設定の対応", "地図上の『検査口』を実際のIDに変えます。", "Link-A RT: 10.20.30.0/24 → <GWLBE-Aのvpce-ID>\nALB-A RT: 10.20.10.0/24 → <同じvpce-ID>\nEndpoint-A RT: 10.20.0.0/16 → local", "これはA→Aの抜粋です。本番2AZでは14章の全組合せを実CIDRへ置換します。", "設計例・S15"),
R("読取確認コマンド", "いまの状態を確認するための例です。", "aws apigatewayv2 get-vpc-link --vpc-link-id <link-id>\naws ec2 describe-route-tables --route-table-ids <rt-id>\naws ec2 describe-vpc-endpoints --vpc-endpoint-ids <vpce-id>\naws elbv2 describe-target-health --target-group-arn <target-group-arn>", "いずれも説明用で未実行です。実行時は対象account/profile/regionを明示し、出力の共有範囲を管理します。", "S03 S16 S20"),
])
